/**
 * First-party `encryption` plugin: exposes an {@link Encrypter} service under a
 * typed service token.
 *
 * `encryptionPlugin()` configures a plugin named `encryption` on the
 * `definePlugin` contract. It takes no options: the keys are secrets, so they
 * come from the environment, the same variables the model encrypter reads.
 * `JSAILS_ENCRYPTION_KEY` (at least 32 characters, generated by tooling when
 * missing) is the primary key and `JSAILS_ENCRYPTION_PREVIOUS_KEYS` the
 * comma-separated decrypt-only keys. A missing or short key fails the run with
 * `config.invalid_env` before any setup; a previous key the encrypter rejects
 * fails setup with a value-free `EncryptionError`.
 *
 * Setup is inert: it constructs an {@link AesEncrypter}, which does no I/O and
 * no crypto until `encrypt`/`decrypt` is called, and returns no cleanup.
 */

import { createServiceToken, type ServiceToken } from '../extensions/services.js';
import { definePlugin, type PluginFactory } from '../plugins/contract/define-plugin.js';
import { envVar } from '../plugins/contract/option-schemas.js';
import { AesEncrypter } from './encrypter.js';
import type { Encrypter } from './encrypter-types.js';
import {
  ENCRYPTION_KEY_ENV,
  ENCRYPTION_PREVIOUS_KEYS_ENV,
  splitPreviousKeys,
} from './model-encrypter.js';

/**
 * Opaque token for the application {@link Encrypter}. Defined once here and
 * shared by the provider (`encryptionPlugin`) and any consumer (a plugin's
 * `requires`, an extension's `requires`).
 */
export const encryptionToken: ServiceToken<Encrypter> = createServiceToken<Encrypter>('encryption');

/**
 * The first-party `encryption` plugin. Call it with no options; the keys are
 * read from the environment when the application runs it.
 */
export const encryptionPlugin: PluginFactory = definePlugin({
  name: 'encryption',
  env: {
    [ENCRYPTION_KEY_ENV]: envVar.secret({ minLength: 32, generate: true }),
    [ENCRYPTION_PREVIOUS_KEYS_ENV]: envVar.string().optional(),
  },
  provides: [encryptionToken],
  setup({ env, services }) {
    const previousKeys = splitPreviousKeys(env[ENCRYPTION_PREVIOUS_KEYS_ENV]);
    services.provide(
      encryptionToken,
      new AesEncrypter({
        key: env[ENCRYPTION_KEY_ENV],
        ...(previousKeys.length === 0 ? {} : { previousKeys }),
      }),
    );
  },
});
